L["Type the new name in the box first."] = "Escribe primero el nuevo nombre en el cuadro."
L["A new, empty plan"] = "Un plan nuevo y vacío"
L["Opens a fresh plan for this class and keeps the open one. Name it in the box first, or it gets a number."] = "Abre un plan nuevo para esta clase y conserva el abierto. Nómbralo antes en el cuadro, o recibe un número."
L["This plan again"] = "Este plan otra vez"
L["Opens a copy of the open plan so you can try changes without touching it. Name it in the box first, or it gets a number."] = "Abre una copia del plan abierto para que pruebes cambios sin tocarlo. Nómbrala antes en el cuadro, o recibe un número."
L["Rename the open plan"] = "Renombrar el plan abierto"
L["Type a name in the box, then press this. Enter does the same."] = "Escribe un nombre en el cuadro y pulsa esto. Intro hace lo mismo."
L["YOUR %s PLANS ON THIS CHARACTER"] = "TUS PLANES DE %s EN ESTE PERSONAJE"
L["%s is on your trees."] = "%s está en tus árboles."
L["%s deleted."] = "%s borrado."
L["The open plan. Apply and the level-up card follow it."] = "El plan abierto. Aplicar y la tarjeta de nivel lo siguen."
L["Click to put it on your trees. The open plan waits here for you, as it is."] = "Haz clic para ponerlo en tus árboles. El plan abierto te espera aquí, tal como está."
L["Show all"] = "Mostrar todo"
L["Back to the whole plan"] = "Volver al plan completo"
L["Looks at your build at level 60 again, with every planned point on the trees."] = "Vuelve a ver tu build a nivel 60, con todos los puntos planificados en los árboles."
L["Apply next point"] = "Aplicar siguiente punto"
L["Places the next point of your plan on your character. Until you press this, nothing on your character changes."] = "Coloca el siguiente punto de tu plan en tu personaje. Hasta que pulses esto, nada cambia en tu personaje."
L["Apply all"] = "Aplicar todo"
